def prefix_only(item, known):
    """Memory item must be a prefix of the answer item (or within drift either way)."""
    lowered = item.lower()
    best = None
    for key, entry in known.items():
        if not lowered.startswith(key):
            continue
        if abs(len(key) - len(lowered)) > DRIFT:
            exact = False
        else:
            exact = True
        score_ = (exact, len(key), entry[1])
        if best is None or score_ > best[0]:
            best = (score_, entry)
    return best[1] if best else None


def prefix_any(item, known):
    """Longest memory item that is a prefix of the answer item, any drift."""
    lowered = item.lower()
    best = None
    for key, entry in known.items():
        if not lowered.startswith(key):
            continue
        score_ = (len(key), entry[1])
        if best is None or score_ > best[0]:
            best = (score_, entry)
    return best[1] if best else None


