    while j < len(rest_item) and j < len(rest_key) \
            and rest_item[len(rest_item) - 1 - j] == rest_key[len(rest_key) - 1 - j]:
        j += 1
    return rest_item[:len(rest_item) - j], rest_key[:len(rest_key) - j]


def matcher(item, known):
    lowered = item.lower()
    best = None
    for key, entry in known.items():
        got = _residuals(lowered, key)
        if got is None:
            continue
        tail_item, tail_key = got
        if abs(len(tail_item) - len(tail_key)) > DRIFT:
            continue
        if not (_subsequence(tail_item, tail_key) or _subsequence(tail_key, tail_item)):
            continue
        score = (len(key), entry[1])
        if best is None or score > best[0]:
            best = (score, entry)
