    """Rule C: report an exactly-known item the memory also writes inside a longer answer."""
    if not isinstance(profile, dict) or not profile.get('vocabulary_like'):
        return ''
    inventory = profile.get('items') or {}
    answers = profile.get('answers') or {}
    if not inventory or not answers:
        return ''
    lines = []
    for item in ac.answer_items(answer):
        if item not in inventory:
            continue
        found = [(text, count) for text, count in answers.items()
                 if text != item and item in ac.split_items(text) and (not seen or text in seen)]
        if not found or len(found) > ac.MAX_TEMPLATES:
            continue
        if sum(count for _, count in found) <= inventory[item]:
            continue
        found.sort(key=lambda entry: (-entry[1], len(entry[0])))
        quoted = ', '.join(ac._written(text, tally) for text, tally in found)
        verb = 'answer' if len(found) == 1 else 'answers'
        lines.append(
            f'- Your answer has "{item}", which the memory writes on its own'
            f' {inventory[item]} time(s); it writes that charge inside the complete {verb}'
            f' {quoted} {sum(c for _, c in found)} time(s).'
        )
        if len(lines) >= ac.MAX_SUGGESTIONS:
            break
    if not lines:
        return ''
    return ac.NOTICE_HEADER + '\n'.join(lines) + ac.NOTICE_FOOTER

